def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp_inc = [1] * n  # Maximum product of increasing subsequence ending at i
    for i in range(n):
        current_max = 1
        for j in range(i):
            if nums[j] < nums[i]:
                current_max = max(current_max, dp_inc[j] * nums[i])
        dp_inc[i] = current_max

    return max(dp_inc)

if __name__ == "__main__":
    assert max_product([3, 100, 4, 5, 150, 6]) == 3000

